// migrations/*.sql is the source of truth (plain SQL, so Vista or any Postgres tooling can run it).
// This embeds it into src/migrations.generated.ts so bundlers never have to find the files at runtime.
// Run: pnpm --filter @rr/db embed   (a test fails if the generated file is stale)
import { readdirSync, readFileSync, writeFileSync } from "node:fs";

const dir = new URL("../migrations/", import.meta.url);
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();
const body = files.map((f) => `  { id: ${JSON.stringify(f.replace(/\.sql$/, ""))}, sql: ${JSON.stringify(readFileSync(new URL(f, dir), "utf8"))} }`).join(",\n");
writeFileSync(new URL("../src/migrations.generated.ts", import.meta.url), `// Generated by scripts/embed-migrations.mjs. Do not edit.\nexport const MIGRATIONS: { id: string; sql: string }[] = [\n${body}\n];\n`);
console.log(`embedded ${files.length} migration(s)`);
